const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Isabela Island straddles the equator. Let's use the equator (0 latitude) as the dividing line.
  // Approximate bounding box for Isabela Island:
  // West: -91.7, East: -91.0, South: -1.0, North: 0.2
  const islandGeometry = ee.Geometry.Polygon(
    [
      [-91.7, -1.0],
      [-91.7, 0.2],
      [-91.0, 0.2],
      [-91.0, -1.0],
      [-91.7, -1.0]
    ],
    null,
    false
  );

  const northernPart = ee.Geometry.Polygon(
    [
      [-91.7, -0.001], // Slightly below equator to ensure no overlap if using 0 for both
      [-91.7, 0.2],
      [-91.0, 0.2],
      [-91.0, -0.001],
      [-91.7, -0.001]
    ],
    null,
    false
  ).intersection(islandGeometry, ee.ErrorMargin(1)); // Intersect with island geometry to refine

  const southernPart = ee.Geometry.Polygon(
    [
      [-91.7, -1.0],
      [-91.7, 0.001], // Slightly above equator
      [-91.0, 0.001],
      [-91.0, -1.0],
      [-91.7, -1.0]
    ],
    null,
    false
  ).intersection(islandGeometry, ee.ErrorMargin(1)); // Intersect with island geometry to refine

  const date = '2022-01-07';
  const scale = 1000; // Resolution for VIIRS DNB is ~750m, use 1000m for reduction to avoid timeouts.

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('NOAA/VIIRS/DNB/VCMCFG_V1_VCMSLCFG')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(islandGeometry)
    .select('avg_rad', 'CF_Pixels'); // Select brightness and cloud mask

  const collectionSize = await collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No VIIRS DNB images found for January 7, 2022 over Isabela Island.");
    console.log("C1");
    return;
  }

  // Expecting a single night-time image for the specified date and region.
  const image = ee.Image(collection.first());

  // Cloud Masking: CF_Pixels values (0: confident clear, 1: probably clear, 2: uncertain, 3: cloudy)
  // Mask out 'uncertain' and 'cloudy' pixels.
  const cloudMask = image.select('CF_Pixels').lte(1); // Keep confident clear (0) and probably clear (1)
  const maskedImage = image.select('avg_rad').updateMask(cloudMask);

  // 3. Processing - Calculate mean brightness for each part
  // Helper function to calculate mean brightness and pixel count
  const calculateBrightness = async (geometry, name) => {
    const pixelsCount = await maskedImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

    if (pixelsCount === 0) {
      console.log(`No valid pixels found for ${name} after cloud masking.`);
      return { mean: null, pixels: 0 };
    }

    const meanBrightness = await maskedImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

    return { mean: meanBrightness, pixels: pixelsCount };
  };

  console.log(`VIIRS images found: ${collectionSize}`);

  const northStats = await calculateBrightness(northernPart, "Northern Part");
  const southStats = await calculateBrightness(southernPart, "Southern Part");

  // 4. Validation & Final Answer
  if (northStats.mean === null || southStats.mean === null || isNaN(northStats.mean) || isNaN(southStats.mean)) {
    console.log("C3"); // Calculation failure if mean is null or NaN
    return;
  }

  console.log(`Northern Part: Mean Brightness = ${northStats.mean !== null ? northStats.mean.toFixed(4) : 'N/A'} nW/cm²/sr, Valid Pixels = ${northStats.pixels}`);
  console.log(`Southern Part: Mean Brightness = ${southStats.mean !== null ? southStats.mean.toFixed(4) : 'N/A'} nW/cm²/sr, Valid Pixels = ${southStats.pixels}`);

  if (northStats.mean > southStats.mean) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
